import React from 'react';

import { dateRangeToLocaleString, getSQLDate } from '@helpers/dateHelper';
import { formatDistance } from '@helpers/formatHelper';
import PohAlert from '@ui-kit/Alert';
import PohAva from '@ui-kit/Ava';
import PohBadge from '@ui-kit/Badge/Badge';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import { showModal } from '@ui-kit/Modal';

import { getWorkouts } from '../../../../Workouts/@services/workouts.service';
import { IWorkout } from '../../../../Workouts/@types/workouts.types';

const SelectWorkoutModal = ({
  d1,
  d2,
  onSave,
}: {
  d1: Date;
  d2: Date;
  onSave: (workout: IWorkout) => void;
}) => {
  const [data, setData] = React.useState<IWorkout[]>([]);
  const [isLoading, setIsLoading] = React.useState(false);
  const [err, setErr] = React.useState<Error>();

  React.useEffect(() => {
    const start = async () => {
      try {
        setIsLoading(true);
        const woRes = await getWorkouts({ d1: getSQLDate(d1), d2: getSQLDate(d2) });
        setData(woRes);
      } catch (e) {
        setErr(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    start();
  }, [d1, d2]);

  if (isLoading) {
    return <PohLoader />;
  }

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }

  return (
    <div style={{ overflowY: 'auto', maxHeight: 400 }}>
      <PohList
        data={data.map((d) => ({
          key: d.id,
          action: true,
          onClick: () => onSave(d),
          content: (
            <div className="d-flex align-items-center justify-content-between">
              <div>
                <strong className="list-item-heading m-0 d-block">
                  {d.name}
                  <small>
                    <PohBadge as="small" className="mx-2">
                      {formatDistance(d.distance)}
                    </PohBadge>
                  </small>
                </strong>
                <small className="text-muted">
                  {dateRangeToLocaleString(d.date_start, d.date_finish)}
                </small>
              </div>
              <aside>
                <small>
                  <PohAva src={d.user.photo} alt={d.user.name} title={d.user.name} />
                </small>
              </aside>
            </div>
          ),
        }))}
      />
    </div>
  );
};

export const selectWorkoutInModalAsync = ({ d1, d2 }: { d1: Date; d2: Date }): Promise<IWorkout> =>
  new Promise((resolve) => {
    showModal({
      title: 'Выбор тренировки',
      children: (closeHandler: any) => (
        <SelectWorkoutModal
          onSave={(res) => {
            resolve(res);
            closeHandler();
          }}
          d1={d1}
          d2={d2}
        />
      ),
    });
  });

export default {};
